import { icon, avatar, logo } from './icons.js';
import { initialData, suggestions } from './data.js';
import { renderSecondary } from './secondary.js';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let saved; try { saved = JSON.parse(localStorage.getItem('workmates-prototype-v1') || 'null'); } catch {}
const data = saved && Array.isArray(saved.agents) && Array.isArray(saved.tasks) ? {...structuredClone(initialData),...saved} : structuredClone(initialData);
const state = {page:'home',agent:'a1',task:null,project:null,detailTab:'Instructions',listTab:'tasks',filter:'all',query:'',libraryFilter:'all',hubFilter:'all',secondaryQuery:'',collapsed:false,mobileOpen:false,model:'Auto',selectedProject:'',capabilities:[],draft:'',attachment:'',recommendation:0,createAvatar:0};
let previousFocus, toastTimer, generationTimers=new Map();
const persist = () => { try { localStorage.setItem('workmates-prototype-v1',JSON.stringify(data)); } catch { toast('当前浏览器未允许保存，数据将在本次会话中保留'); } };
const agentBy = id => data.agents.find(a=>a.id===id) || data.agents[0];
const taskBy = id => data.tasks.find(t=>t.id===id);
const button = (action,label,ic='',extra='',cls='btn') => `<button class="${cls}" data-action="${action}" ${extra}>${ic?icon(ic,16):''}${label}</button>`;
const iconButton=(action,name,label,extra='')=>{const match=extra.match(/class="([^"]*)"/);const classes=match?' '+match[1]:'';return `<button class="icon-btn${classes}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra.replace(/class="[^"]*"/,'')}>${icon(name,17)}</button>`;};
const menuItem=(action,label,name='',extra='',checked=false)=>`<button class="menu-item" data-action="${action}" ${extra}>${name?icon(name,16):''}<span>${esc(label)}</span>${checked?`<span class="menu-check">${icon('check',14)}</span>`:''}</button>`;
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('checkcircle',18)+`<span>${esc(message)}</span>`;$('#toast-root').replaceChildren(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200);}
function closeOverlay(){const overlay=$('#overlay-root');overlay.innerHTML='';document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
function modal(title,body,footer='',className=''){previousFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop="true"><section class="modal ${className}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2>${iconButton('close','close','Close')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay-root input, #overlay-root textarea, #overlay-root button')?.focus(),30);}
function popover(el,content){previousFocus=el;const rect=el.getBoundingClientRect();$('#overlay-root').innerHTML=`<div class="popover-backdrop" data-action="close"></div><div class="popover" role="menu">${content}</div>`;const p=$('.popover');p.style.left=Math.max(8,Math.min(rect.left,innerWidth-p.offsetWidth-12))+'px';p.style.top=(rect.bottom+p.offsetHeight+8>innerHeight?Math.max(8,rect.top-p.offsetHeight-6):rect.bottom+6)+'px';p.querySelector('button')?.focus();}
function navigate(page,id){closeOverlay();state.page=page;state.query='';state.filter='all';state.listTab='tasks';state.mobileOpen=false;if(page==='detail'){state.agent=id||state.agent;state.detailTab='Instructions';}if(page==='task'){state.task=id;const t=taskBy(id);if(t){t.unread=false;state.agent=t.agent;persist();}}if(page==='project')state.project=id;if(page==='new'&&id)state.agent=id;const hash=page+(id?'/'+id:'');if(location.hash.slice(1)!==hash)history.pushState({},'',`#${hash}`);render();window.scrollTo(0,0);}
function readRoute(){const [page,id]=location.hash.slice(1).split('/');if(['home','new','detail','task','automations','projects','project','library','hub','code'].includes(page)){state.page=page;if(page==='detail'||page==='new')state.agent=id||'a1';if(page==='task'){state.task=id;if(!taskBy(id))state.page='home';else state.agent=taskBy(id).agent;}if(page==='project'){state.project=id;if(!data.projects.some(p=>p.id===id))state.page='projects';}}render();}
function sidebar(){const nav=[['home','home','Home'],['new','edit','New Task'],['automations','bolt','Automations'],['projects','folder','Projects'],['library','library','Library'],['hub','hub','Hub']];return `<aside class="sidebar" ${state.collapsed||innerWidth<=680&&!state.mobileOpen?'inert':''}><div class="brand"><button class="brand-logo" data-action="nav" data-page="home" aria-label="Workmates home">${logo()}</button><div class="brand-word">Doubao <span>Workmates</span></div><div class="brand-actions">${iconButton('global-search','search','Search · ⌘K')}${iconButton('collapse','collapse','Collapse sidebar')}</div></div><div class="mode-switch" role="tablist" aria-label="Workspace mode"><button role="tab" aria-selected="${state.page!=='code'}" class="${state.page!=='code'?'active':''}" data-action="nav" data-page="home">${icon('grid',12)}Work</button><button role="tab" aria-selected="${state.page==='code'}" class="${state.page==='code'?'active':''}" data-action="nav" data-page="code">${icon('code',13)}Code</button></div><nav class="main-nav" aria-label="Main navigation">${nav.map(([page,ic,label])=>`<a href="#${page}" class="nav-item ${state.page===page||page==='projects'&&state.page==='project'?'active':''}" data-action="nav" data-page="${page}" ${state.page===page?'aria-current="page"':''}>${icon(ic,18)}<span>${label}</span>${page==='hub'?'<small>Experts · Skills</small>':''}</a>`).join('')}</nav><section class="sidebar-tasks"><div class="sidebar-label"><button data-action="nav" data-page="home">Tasks</button>${iconButton('sidebar-settings','settings','Task list settings')}</div>${data.tasks.filter(t=>!t.archived).sort((a,b)=>(!!b.pinned)-(!!a.pinned)).slice(0,16).map(t=>`<div class="sidebar-task ${state.page==='task'&&state.task===t.id?'current':''}"><button class="task-title" title="${esc(t.name)}" data-action="open-task" data-id="${t.id}">${t.pinned?icon('star',12)+' ':''}${esc(t.name)}</button>${t.unread?'<span class="dot"></span>':''}${iconButton('task-menu','more','More actions for '+t.name,`data-id="${t.id}"`)}</div>`).join('')}</section><div class="sidebar-footer"><button class="profile-btn" data-action="profile"><span class="profile-avatar">设计</span><span>设计工作空间</span></button>${iconButton('proactive','moon','Proactive help')}<button class="icon-btn notice-btn" data-action="notifications" aria-label="Notifications">${icon('bell',18)}${!data.notificationsRead?'<span class="notice-badge">1</span>':''}</button></div></aside>`;}
function render(){for(const p of data.projects)p.tasks=data.tasks.filter(t=>t.project===p.id&&!t.archived).length;const secondary=['automations','projects','library','hub','code'];let content=state.page==='home'?home():state.page==='new'?newTask():state.page==='detail'?details():state.page==='task'?chat():state.page==='project'?projectPage():secondary.includes(state.page)?renderSecondary(state.page,{...data,icon,avatar,escape:esc,query:state.secondaryQuery,libraryFilter:state.libraryFilter,hubFilter:state.hubFilter}):home();$('#app').innerHTML=`<div class="app-layout ${state.collapsed?'collapsed':''} ${state.mobileOpen?'mobile-open':''}"><div class="mobile-scrim" data-action="collapse"></div>${sidebar()}<button class="icon-btn floating-expand" data-action="expand" aria-label="Expand sidebar">${icon('collapse',18)}</button><main class="main" id="main-content">${content}</main></div>`;document.title=`${{home:'Home',new:'New Task',detail:agentBy(state.agent).name,task:taskBy(state.task)?.name,automations:'Automations',projects:'Projects',library:'Library',hub:'Hub',code:'Code',project:'Project'}[state.page]} · Workmates`;
if(state.page==='task')setTimeout(()=>{const scroll=$('.chat-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;},0);}
function agentCard(a){return `<article class="agent-card" tabindex="0" role="button" aria-label="View ${esc(a.name)}" data-action="agent-detail" data-id="${a.id}"><div class="agent-card-top">${avatar(a.avatar,36)}<span class="agent-card-name" title="${esc(a.name)}">${esc(a.name)}</span><button class="chat-button" data-action="chat-agent" data-id="${a.id}" aria-label="Chat with ${esc(a.name)}">${icon('chat',16)}</button></div><div class="agent-desc">${esc(a.description)}</div><div class="agent-meta"><span>${icon('chat',12)}${a.tasks}</span><span>${icon(a.tag==='Squads'?'users':'layers',12)}${a.skills}</span>${a.tag?`<span class="tag">${esc(a.tag)}</span>`:''}</div></article>`;}
function home(){return `<div class="home-page"><section><div class="section-heading"><h1>Workmates and squads</h1><div class="heading-actions"><button class="text-btn" data-action="create-menu">${icon('plus',14)}Create</button><span class="divider"></span><button class="text-btn" data-action="nav" data-page="hub">All ${icon('chevron',11)}</button></div></div><div class="agents-grid">${data.agents.map(agentCard).join('')}</div></section>${!data.hideQuick?`<section class="quick-section"><div class="section-heading"><h2>Quick start</h2><button class="text-btn" data-action="hide-quick">Don't Show Again</button></div><div class="quick-grid"><div class="quick-card quick-add"><h3>Add more Workmates</h3><p>Find skilled Workmates ready to work for you.</p><button class="quick-action" data-action="nav" data-page="hub">${icon('grid',15)}Browse Workmates</button><button class="quick-action" data-action="create-agent">${icon('users',17)}Create a Workmate</button></div><div class="quick-card"><div class="quick-card-head"><h3>Kick off a task</h3>${iconButton('refresh-recommendations','refresh','Refresh recommendations')}</div>${[0,1,2].map(n=>{let idx=(n+state.recommendation)%suggestions.length,s=suggestions[idx];return `<button class="recommendation" data-action="suggestion" data-index="${idx}">${avatar(agentBy(s.agent).avatar,20)}<span>${esc(s.text)}</span>${icon('arrow',15)}</button>`;}).join('')}</div></div></section>`:''}${taskSection()}</div>`;}
function taskSection(){return `<section class="task-section"><div class="list-toolbar"><div class="tabs" role="tablist" aria-label="Recent activity">${['tasks','automations',...(state.page==='new'?['artifacts']:[])].map(t=>`<button class="tab-btn ${state.listTab===t?'active':''}" role="tab" aria-selected="${state.listTab===t}" data-action="list-tab" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="list-tools">${iconButton('filter','filter','Filter tasks',`class="filter-btn"`)}<label class="search-field">${icon('search',16)}<input data-task-search value="${esc(state.query)}" placeholder="Search" aria-label="Search tasks"></label></div></div><div id="task-results">${taskRows()}</div></section>`;}
function taskRows(){if(state.listTab==='automations')return data.automations.filter(a=>a.name.toLowerCase().includes(state.query.toLowerCase())).map(a=>`<div class="task-row"><button class="task-open" data-action="nav" data-page="automations">${icon('clock',20)}<span>${esc(a.name)}</span></button><span class="task-date">${a.enabled?'Active':'Paused'} · ${esc(a.schedule)}</span></div>`).join('')||empty('No automations found','试试其他关键词');if(state.listTab==='artifacts')return data.library.filter(f=>f.name.toLowerCase().includes(state.query.toLowerCase())).map(f=>`<div class="task-row"><button class="task-open" data-action="open-file" data-id="${f.id}">${icon('file',20)}${esc(f.name)}</button><span class="task-date">${esc(f.updated)}</span></div>`).join('')||empty('No files found','试试其他关键词');const tasks=data.tasks.filter(t=>(state.filter==='archived'?t.archived:!t.archived)&&t.name.toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='all'||state.filter==='archived'||state.filter==='unread'&&t.unread||state.filter==='pinned'&&t.pinned||state.filter==='done'&&t.status==='done')).sort((a,b)=>(!!b.pinned)-(!!a.pinned));return tasks.length?tasks.map(t=>`<div class="task-row"><button class="task-open" data-action="open-task" data-id="${t.id}">${state.page==='home'?avatar(agentBy(t.agent).avatar,24):''}<span class="ellipsis">${esc(t.name)}${t.unread?'<span class="dot"></span>':''}</span></button><span class="task-date">${esc(t.date)}</span><button class="icon-btn task-more" aria-label="More ${esc(t.name)}" data-action="task-menu" data-id="${t.id}">${icon('more',17)}</button></div>`).join(''):empty('No tasks found','试试其他关键词，或创建一个新任务。');}
function empty(title,description){return `<div class="empty-state">${icon('search',25)}<h3>${title}</h3><p>${description}</p></div>`;}
function composer(followup=false){return `<div class="composer">${state.attachment?`<div class="attachment-pill">${icon('file',14)}${esc(state.attachment)}${iconButton('remove-attachment','close','Remove attachment')}</div>`:''}<textarea id="task-prompt" aria-label="Task or goal" placeholder="${followup?'Ask a follow-up…':"What's your task or goal?"}" rows="2">${esc(state.draft)}</textarea><div class="composer-bottom">${iconButton('attach-menu','plus','Add attachment')}<span class="separator"></span><button class="chip-btn" data-action="select-project">${icon('folder',15)}<span>${esc(data.projects.find(p=>p.id===state.selectedProject)?.name||'Select project')}</span>${icon('chevron',10)}</button>${['Slides','Deep Research'].map((c,n)=>`<button class="chip-btn capability-chip ${state.capabilities.includes(c)?'active':''}" data-action="capability" data-value="${c}">${icon(n?'globe':'file',15)}${c}</button>`).join('')}<button class="chip-btn more-cap" data-action="more-capabilities">${icon('grid',15)}More</button><button class="chip-btn model" data-action="select-model">${esc(state.model)}${icon('chevron',10)}</button>${iconButton('voice','mic','Voice input','class="mic-control"')}<button class="send-btn" data-action="send-task" aria-label="Send task" ${!state.draft.trim()?'disabled':''}>${icon('arrow',23)}</button></div></div>`;}
function newTask(){const a=agentBy(state.agent);return `<div class="new-page"><div class="new-hero"><div class="agent-greeting">${avatar(a.avatar,56)}<button class="greeting-name" data-action="select-agent">${esc(a.name)}<span style="transform:rotate(90deg);display:inline-flex">${icon('chevron',13)}</span></button><button class="text-btn details-link" data-action="agent-detail" data-id="${a.id}">Workmate Details ${icon('chevron',12)}</button></div>${composer()}</div><section class="for-you"><div class="for-you-title"><h2>For You</h2><p>Here are a few recommended tasks based on your recent activity:</p></div><div class="suggestion-grid">${[3,4,0].map(index=>{const s=suggestions[index];return `<button class="suggestion-card" data-action="fill-suggestion" data-index="${index}"><span class="suggestion-label">${icon(s.icon,13)}${s.label}</span><p>${esc(s.text)}</p></button>`;}).join('')}</div></section>${taskSection()}</div>`;}
function details(){const a=agentBy(state.agent),tabs=['Instructions','Capabilities','Work Context','Feishu Settings','Manage'];let body='';if(state.detailTab==='Instructions')body=`<div class="detail-label"><h2>Instructions</h2>${button('edit-instructions','Edit','edit')}</div><div class="instruction-box">${esc(a.instructions||'你是一位可靠、细致的智能工作伙伴。\n\n理解用户的任务与目标，主动梳理上下文，将复杂问题拆解为可以执行的步骤。\n\n工作原则\n1. 先明确问题与预期结果，再制定行动方案。\n2. 提供结构清晰、简洁准确的回答，并说明关键假设。\n3. 在需要时使用合适的工具，交付可直接使用的成果。\n4. 涉及重要决策时，与用户确认后再执行。')}</div>`;if(state.detailTab==='Capabilities')body=`<div class="detail-label"><h2>Skills & tools</h2>${button('add-capability','Add capability','plus')}</div><div class="capability-grid">${[['file','文档与写作','整理资料、提炼观点，生成专业文档。'],['globe','深度调研','梳理问题，形成完整的研究框架。'],['code','代码与开发','理解代码，协助开发与故障排查。'],['grid','数据分析','清理数据，探索趋势与关键洞察。'],['play','演示文稿','将想法整理成清晰的汇报材料。'],['users','团队协作','拆解任务，协调伙伴与工作进度。'],...(a.extraSkills||[]).map(s=>['layers',s,'已添加到当前伙伴的演示能力。'])].map(([ic,title,desc])=>`<div class="capability-item">${icon(ic,22)}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`).join('')}</div>`;if(state.detailTab==='Work Context')body=`<div class="detail-label"><h2>Work context</h2>${button('add-context','Add context','plus')}</div><p class="muted">给伙伴一些工作背景，让每次协作更有默契。</p><div class="instruction-box">${esc(a.context||'工作目标：提升产品体验与团队协作效率。\n偏好语言：中文\n输出偏好：先给结论，再展开关键依据与下一步行动。')}</div>`;if(state.detailTab==='Feishu Settings')body=`<h2>Feishu connection</h2><div class="instruction-box"><div class="row">${icon('globe',21)}<strong>飞书工作空间</strong><span class="tag">Demo</span></div><p>当前为交互原型，连接流程使用演示状态。</p>${button('demo-connect',a.demoConnected?'Disconnect demo':'Connect Feishu','external')}</div>`;if(state.detailTab==='Manage')body=`<h2>Workmate settings</h2><div class="instruction-box"><div class="detail-label"><div>Basic information<p class="muted" style="font-size:12px;margin:4px 0">名称、介绍与伙伴头像</p></div>${button('edit-agent','Edit','edit',`data-id="${a.id}"`)}</div><div class="detail-label"><div>Display on Home<p class="muted" style="font-size:12px;margin:4px 0">当前伙伴已添加至你的工作台</p></div>${icon('checkcircle',20)}</div></div>`;return `<div class="detail-page"><div class="breadcrumbs"><button data-action="nav" data-page="home">Home</button>${icon('chevron',12)}<button data-action="chat-agent" data-id="${a.id}">${esc(a.name)}</button>${icon('chevron',12)}<span>Details</span>${iconButton('agent-menu','more','More workmate actions',`data-id="${a.id}" style="margin-left:auto"`)}</div><section class="agent-profile">${avatar(a.avatar,64)}<div class="grow"><div class="row"><h1>${esc(a.name)}</h1>${a.tag?`<span class="tag">${esc(a.tag)}</span>`:''}${iconButton('edit-agent','edit','Edit basic info',`data-id="${a.id}"`)}</div><p>${esc(a.description)}</p><div class="profile-controls"><button class="soft-chip" data-action="select-model">${icon('star',12)}${esc(state.model)}${icon('chevron',10)}</button><button class="soft-chip" data-action="proactive">${icon('moon',12)}Proactive help ${data.proactive?'enabled':'not enabled'} ${icon('chevron',10)}</button></div></div><div class="profile-cta">${button('feishu-chat','Chat in Feishu','chat')}${button('chat-agent','New Task','edit',`data-id="${a.id}"`)}</div></section><div class="detail-tabs"><div class="tabs underlined" role="tablist">${tabs.map(t=>`<button class="tab-btn ${state.detailTab===t?'active':''}" role="tab" aria-selected="${state.detailTab===t}" data-action="detail-tab" data-tab="${t}">${t}</button>`).join('')}</div></div><div class="detail-body">${body}</div></div>`;}
function answerMarkup(t){if(t.status==='running')return `<div class="progress-line"><span class="pulse"></span>正在整理任务与生成演示结果…</div><p>我会先梳理任务目标，再整理执行步骤和交付内容。</p>`;const isCode=t.kind==='code',isResearch=/调研|研究|Research/.test(t.name);return `<div class="progress-line">${icon('checkcircle',14)}任务已完成 <span class="demo-badge">演示结果</span></div><p>已收到你的需求：${esc(t.prompt||t.name)}。</p><p>下面是一份用于体验任务流程的示例结果，你可以继续补充要求，或预览右下方的交付文件。</p><h3>${isCode?'实现方案':isResearch?'调研框架与关键结论':'工作梳理与执行建议'}</h3><ol><li><strong>明确目标与范围</strong>：聚焦主要使用场景，定义预期成果和验收标准。</li><li><strong>${isCode?'梳理页面与交互':'整理信息与优先级'}</strong>：${isCode?'拆解页面结构、组件状态和用户操作路径。':'将现有内容归纳为关键进展、待解决问题与下一步计划。'}</li><li><strong>形成可执行方案</strong>：按影响范围与投入成本安排优先级，确保每项行动都有明确结果。</li></ol><h3>下一步</h3><p>先完成核心场景的验证，再结合反馈持续完善细节。你也可以让我将内容调整为汇报稿、任务清单或演示文稿。</p><button class="answer-artifact" data-action="open-file" data-id="${esc(t.file||'f1')}"><span class="artifact-icon">${icon('file',22)}</span><span class="grow"><strong>${esc(t.name)} · 交付文档</strong><br><small>Document · Click to preview</small></span>${icon('chevron',16)}</button><div class="row">${iconButton('copy-answer','copy','Copy answer',`data-id="${t.id}"`)}${button('followup-suggestion','整理为行动清单','','','soft-chip')}</div>`;}
function chat(){const t=taskBy(state.task);if(!t)return home();const a=agentBy(t.agent);return `<div class="chat-page"><header class="chat-header">${avatar(a.avatar,29)}<h1 title="${esc(t.name)}">${esc(t.name)}</h1>${iconButton('task-menu','more','Task actions',`data-id="${t.id}"`)}${iconButton('agent-detail','settings','Workmate details',`data-id="${a.id}"`)}</header><div class="chat-scroll"><div class="chat-user">${esc(t.prompt||t.name)}${t.attachment?`<div class="attachment-pill" style="margin:10px 0 0;background:white">${icon('file',14)}${esc(t.attachment)}</div>`:''}${t.capabilities?.length?`<div class="prototype-note" style="margin-top:8px">${esc(t.capabilities.join(' · '))} · ${esc(t.model||'Auto')}</div>`:''}</div><div class="assistant-header">${avatar(a.avatar,29)}${esc(a.name)}<span class="demo-badge">Prototype</span></div><div class="assistant-answer">${answerMarkup(t)}</div>${(t.replies||[]).map(r=>`<div class="chat-user" style="margin-top:28px">${esc(r.prompt)}</div><div class="assistant-header">${avatar(a.avatar,29)}${esc(a.name)}</div><div class="assistant-answer"><p>已根据「${esc(r.prompt)}」更新演示方案。可以按以下三个阶段推进：</p><ol><li>准备：整理输入资料，明确工作目标。</li><li>执行：拆解行动项，完成核心内容。</li><li>交付：检查结果，记录反馈与改进点。</li></ol><p class="prototype-note">以上为本地原型的预设交互反馈。</p></div>`).join('')}</div><div class="chat-composer">${composer(true)}<div class="chat-footnote">交互原型 · 使用演示数据，任务和自动化不会在真实飞书中执行</div></div></div>`;}
function projectPage(){const p=data.projects.find(p=>p.id===state.project);if(!p)return renderSecondary('projects',{...data,icon,avatar,escape:esc});const tasks=data.tasks.filter(t=>t.project===p.id&&!t.archived);return `<div class="detail-page"><div class="breadcrumbs"><button data-action="nav" data-page="projects">Projects</button>${icon('chevron',12)}<span>${esc(p.name)}</span></div><div class="agent-profile"><span class="artifact-icon" style="width:58px;height:58px">${icon('folder',28)}</span><div class="grow"><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p></div>${button('project-new-task','New task','plus',`data-id="${p.id}"`)}</div><div class="detail-tabs"><div class="tabs underlined"><span class="tab-btn active" style="display:flex;align-items:center">Tasks</span></div></div>${tasks.length?tasks.map(t=>`<div class="task-row"><button class="task-open" data-action="open-task" data-id="${t.id}">${avatar(agentBy(t.agent).avatar,24)}${esc(t.name)}</button><span class="task-date">${esc(t.date)}</span></div>`).join(''):`<div class="empty-state">${icon('folder',36)}<h3>A fresh space for your next idea</h3><p>从一个任务开始，让你的伙伴了解这个项目。</p>${button('project-new-task','Create a task','plus',`data-id="${p.id}"`)}</div>`}</div>`;}
function showSearch(query=''){previousFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop="true"><section class="modal search-modal" role="dialog" aria-modal="true" aria-label="Search everything"><div class="global-search-box">${icon('search',22)}<input id="global-search" placeholder="Search tasks, workmates, and projects…" aria-label="Search everything" value="${esc(query)}" autocomplete="off"><button class="kbd" data-action="close">Esc</button></div><div id="global-results" class="search-results">${searchResults(query)}</div><div class="modal-footer" style="justify-content:space-between;font-size:11px;color:#9ca1a8;padding:10px 20px"><span>Find something to pick up where you left off</span><span>⌘ K</span></div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#global-search')?.focus(),20);}
function searchResults(query){const q=query.trim().toLowerCase(),groups=[['Workmates',data.agents.filter(a=>(a.name+' '+a.description).toLowerCase().includes(q)).slice(0,4),a=>`<button class="search-result" data-action="agent-detail" data-id="${a.id}">${avatar(a.avatar,26)}<span>${esc(a.name)}</span>${icon('chevron',13)}</button>`],['Tasks',data.tasks.filter(t=>!t.archived&&t.name.toLowerCase().includes(q)).slice(0,6),t=>`<button class="search-result" data-action="open-task" data-id="${t.id}">${icon('chat',19)}<span>${esc(t.name)}</span>${icon('chevron',13)}</button>`],['Projects',data.projects.filter(p=>p.name.toLowerCase().includes(q)).slice(0,3),p=>`<button class="search-result" data-action="open-project" data-id="${p.id}">${icon('folder',19)}<span>${esc(p.name)}</span>${icon('chevron',13)}</button>`]];return groups.filter(([,items])=>items.length).map(([name,items,renderer])=>`<div class="search-caption">${name}</div>${items.map(renderer).join('')}`).join('')||empty('No results found','换一个关键词试试');}
function createAgent(editId,squad=false){const a=editId?agentBy(editId):null;state.createAvatar=a?.avatar??(squad?5:0);modal(a?'Edit workmate':squad?'Create a squad':'Create a Workmate',`<form id="agent-form" data-edit="${a?.id||''}"><div class="avatar-options">${[0,1,2,3,4,5].map(i=>`<button type="button" class="avatar-option ${i===state.createAvatar?'selected':''}" data-action="pick-avatar" data-value="${i}" aria-label="Avatar ${i+1}" aria-pressed="${i===state.createAvatar}">${avatar(i,42)}</button>`).join('')}</div><label class="form-field"><span>Name <span class="muted">*</span></span><input name="name" placeholder="Give your workmate a name" value="${esc(a?.name||'')}" maxlength="40" required></label><label class="form-field"><span>Description</span><textarea name="description" placeholder="What can this workmate help you with?" maxlength="300">${esc(a?.description==='No description yet'?'':a?.description||'')}</textarea></label><label class="form-field"><span>Type</span><select name="tag">${['Personal','Team','Third-party','Squads'].map(tag=>`<option ${tag===(a?.tag||(squad?'Squads':'Personal'))?'selected':''}>${tag}</option>`).join('')}</select></label><p class="prototype-note">保存在此浏览器中，随时可以编辑。</p></form>`,button('close','Cancel')+button('save-agent',a?'Save changes':'Create Workmate','','','btn primary'));setTimeout(()=>$('#agent-form input')?.focus(),40);}
function createAutomation(){modal('New automation',`<form id="automation-form"><label class="form-field"><span>Name <span class="muted">*</span></span><input name="name" placeholder="e.g. 每周工作报告" maxlength="60" required></label><label class="form-field"><span>Task instructions <span class="muted">*</span></span><textarea name="description" placeholder="Describe what your workmate should do…" required></textarea></label><label class="form-field"><span>Schedule</span><select name="frequency"><option value="Every weekday">Every weekday</option><option value="Every day">Every day</option><option value="Every Monday">Every Monday</option><option value="Every Friday">Every Friday</option></select></label><label class="form-field"><span>Time</span><input type="time" name="time" value="09:00" required></label><p class="prototype-note">原型仅演示自动化配置与状态切换，不会真正定时执行。</p></form>`,button('close','Cancel')+button('save-automation','Create automation','','','btn primary'));}
function createProject(){modal('New project',`<form id="project-form"><label class="form-field"><span>Project name <span class="muted">*</span></span><input name="name" placeholder="What are you working on?" required maxlength="60"></label><label class="form-field"><span>Description</span><textarea name="description" placeholder="A little context goes a long way…"></textarea></label></form>`,button('close','Cancel')+button('save-project','Create project','','','btn primary'));}
function showFile(id){const f=data.library.find(f=>f.id===id)||data.library[0];const body=f.content||'这是一份用于展示交互流程的示例文档。内容由原型预设，可用于体验预览、下载与任务交付。\n\n项目目标\n聚焦核心使用场景，提升信息获取效率与团队协作体验。\n\n关键行动\n1. 明确目标：梳理需求，约定交付范围。\n2. 方案设计：完成信息结构和主要用户路径。\n3. 验证迭代：收集反馈，逐步完善细节。\n\n下一步计划\n围绕核心场景完成第一轮验证，并整理具体的改进清单。';modal(f.name,`<div class="row" style="margin-bottom:17px;color:#8f959e;font-size:12px">${icon('file',15)}${{doc:'Document',slides:'Presentation preview',sheet:'Spreadsheet preview'}[f.type]} · ${esc(f.updated)}<span class="demo-badge">Demo content</span></div><div class="file-preview"><h2>${esc(f.name)}</h2>${esc(body)}</div>`,button('close','Close')+button('download-file','Download .md','download',`data-id="${f.id}"`,'btn primary'));}
function notifications(){previousFocus=document.activeElement;data.notificationsRead=true;persist();render();$('#overlay-root').innerHTML=`<div class="overlay drawer-overlay" data-backdrop="true"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Notifications"><div class="modal-header"><h2>Notifications</h2>${iconButton('close','close','Close notifications')}</div><div class="modal-body"><p class="muted" style="font-size:12px">You’re all caught up.</p><button class="notice-item" data-action="open-task" data-id="t2" style="text-align:left;width:100%"><span class="notification-icon">${icon('checkcircle',20)}</span><span><strong>你的智能伙伴已完成任务</strong><p>「创建周报自动生成编排技能」已经完成，点击查看任务结果。</p><small>Today · 17:54</small></span></button><div class="notice-item"><span class="notification-icon" style="color:#6c82c9;background:#f0f3fc">${icon('users',20)}</span><div><strong>欢迎来到你的 Workmates 工作台</strong><p>选择一个智能伙伴，开始你的第一个任务。</p><small>Getting started</small></div></div></div></aside></div>`;document.body.style.overflow='hidden';}
function startTask(prompt,kind='work'){const text=prompt.trim();if(!text)return;const id='t'+Date.now(),fileId='f'+Date.now();const currentAgent=kind==='code'?'a3':state.agent;const date=new Date().toLocaleString('en-US',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).replace(',','');data.tasks.unshift({id,name:text.length>30?text.slice(0,30)+'…':text,prompt:text,date,agent:currentAgent,status:'running',project:state.selectedProject,file:fileId,kind,attachment:state.attachment,model:state.model,capabilities:[...state.capabilities]});agentBy(currentAgent).tasks++;data.library.unshift({id:fileId,name:text.slice(0,24)+' · 交付文档',type:'doc',updated:'Just now',content:`任务目标\n${text}\n\n执行方案\n1. 明确问题与预期结果。\n2. 将任务拆解为可执行的步骤。\n3. 完成核心工作，并检查交付质量。\n\n这是一份本地交互原型的预设演示结果，未调用真实 AI 服务。`});const project=data.projects.find(p=>p.id===state.selectedProject);if(project)project.tasks=(project.tasks||0)+1;state.draft='';state.attachment='';persist();navigate('task',id);const timer=setTimeout(()=>{const t=taskBy(id);if(t){t.status='done';t.unread=state.task!==id||state.page!=='task';persist();if(state.page==='task'&&state.task===id)render();else toast('智能伙伴已完成演示任务');}generationTimers.delete(id);},1600);generationTimers.set(id,timer);}
function downloadFile(id){const f=data.library.find(f=>f.id===id);if(!f)return;const content=`# ${f.name}\n\n${f.content||'这是一份高仿真交互原型中的示例交付文档。\n\n## 项目目标\n聚焦核心使用场景，提升协作效率。\n\n## 下一步\n- 明确需求范围\n- 完成方案设计\n- 收集反馈并迭代'}\n\n---\nWorkmates 产品交互原型 · 演示内容`;const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=f.name+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('文档已下载');}

async function action(el,event){const a=el.dataset.action,id=el.dataset.id;
if(a==='close'){closeOverlay();return;}
if(a==='nav'){event.preventDefault();navigate(el.dataset.page);return;}
if(a==='collapse'){if(innerWidth<=680)state.mobileOpen=false;else state.collapsed=true;render();return;}
if(a==='expand'){state.collapsed=false;if(innerWidth<=680)state.mobileOpen=true;render();return;}
if(a==='global-search'){showSearch();return;}
if(a==='open-task'){navigate('task',id);return;}
if(a==='agent-detail'){navigate('detail',id);return;}
if(a==='chat-agent'){state.draft='';navigate('new',id);return;}
if(a==='create-menu'){popover(el,menuItem('create-agent','Create a Workmate','users')+menuItem('create-squad','Create a squad','layers'));return;}
if(a==='create-agent'||a==='create-squad'||a==='edit-agent'){closeOverlay();createAgent(a==='edit-agent'?id:null,a==='create-squad');return;}
if(a==='pick-avatar'){state.createAvatar=Number(el.dataset.value);document.querySelectorAll('.avatar-option').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el);});return;}
if(a==='save-agent'){const form=$('#agent-form');if(!form.reportValidity())return;const values=new FormData(form),name=values.get('name').trim();if(!name){form.elements.name.setCustomValidity('请输入伙伴名称');form.reportValidity();form.elements.name.setCustomValidity('');return;}const changes={name,description:values.get('description').trim()||'No description yet',tag:values.get('tag'),avatar:state.createAvatar};if(form.dataset.edit)Object.assign(agentBy(form.dataset.edit),changes);else data.agents.push({id:'a'+Date.now(),...changes,tasks:0,skills:0});persist();closeOverlay();render();toast(form.dataset.edit?'伙伴信息已更新':'已创建新的智能伙伴');return;}
if(a==='hide-quick'){data.hideQuick=true;persist();render();toast('已隐藏 Quick start，可在工作空间菜单中恢复');return;}
if(a==='restore-quick'){data.hideQuick=false;persist();navigate('home');toast('已恢复 Quick start');return;}
if(a==='refresh-recommendations'){state.recommendation=(state.recommendation+3)%suggestions.length;render();return;}
if(a==='suggestion'||a==='fill-suggestion'){const s=suggestions[Number(el.dataset.index)];state.draft=s.text;state.capabilities=s.label==='Slides'||s.label==='Deep Research'?[s.label]:[];if(a==='suggestion')navigate('new',s.agent);else render();$('#task-prompt')?.focus();return;}
if(a==='list-tab'){state.listTab=el.dataset.tab;state.query='';render();return;}
if(a==='filter'){popover(el,`<div class="menu-caption">Show tasks</div>`+[['all','All tasks'],['unread','Unread'],['pinned','Pinned'],['done','Completed'],['archived','Archived']].map(([value,label])=>menuItem('set-filter',label,'',`data-value="${value}"`,state.filter===value)).join(''));return;}
if(a==='set-filter'){state.filter=el.dataset.value;closeOverlay();$('#task-results').innerHTML=taskRows();document.querySelector('[data-action="filter"]')?.classList.toggle('selected',state.filter!=='all');return;}
if(a==='sidebar-settings'){popover(el,menuItem('show-unread','Unread tasks','bell')+menuItem('show-archived','Archived tasks','folder')+menuItem('global-search','Search tasks','search')+menuItem('restore-quick','Show Quick start','grid'));return;}
if(a==='show-unread'||a==='show-archived'){navigate('home');state.filter=a==='show-unread'?'unread':'archived';render();document.querySelector('.task-section')?.scrollIntoView({behavior:'smooth'});return;}
if(a==='task-menu'){const t=taskBy(id);if(!t)return;popover(el,menuItem('pin-task',t.pinned?'Unpin task':'Pin task','star',`data-id="${id}"`)+menuItem('rename-task','Rename','edit',`data-id="${id}"`)+menuItem('archive-task',t.archived?'Restore task':'Archive task','folder',`data-id="${id}"`));return;}
if(a==='pin-task'||a==='archive-task'){const t=taskBy(id);if(!t)return;if(a==='pin-task')t.pinned=!t.pinned;else t.archived=!t.archived;persist();closeOverlay();render();toast(a==='pin-task'?(t.pinned?'任务已置顶':'已取消置顶'):(t.archived?'任务已归档，可在筛选中恢复':'任务已恢复'));return;}
if(a==='rename-task'){const t=taskBy(id);closeOverlay();modal('Rename task',`<form id="rename-form"><label class="form-field"><span>Task name</span><input name="name" value="${esc(t.name)}" required maxlength="100"></label></form>`,button('close','Cancel')+button('save-task-name','Save','','data-id="'+id+'"','btn primary'));return;}
if(a==='save-task-name'){const form=$('#rename-form');if(!form.reportValidity())return;const name=form.elements.name.value.trim();if(!name)return;taskBy(id).name=name;persist();closeOverlay();render();toast('任务名称已更新');return;}
if(a==='select-agent'){popover(el,`<div class="menu-caption">Choose a workmate</div>`+data.agents.map(agent=>`<button class="menu-item" data-action="choose-agent" data-id="${agent.id}">${avatar(agent.avatar,26)}<span>${esc(agent.name)}</span>${agent.id===state.agent?'<span class="menu-check">'+icon('check',14)+'</span>':''}</button>`).join(''));return;}
if(a==='choose-agent'){state.agent=id;closeOverlay();render();return;}
if(a==='select-project'){popover(el,menuItem('choose-project','No project','folder','data-id=""',!state.selectedProject)+data.projects.map(p=>menuItem('choose-project',p.name,'folder',`data-id="${p.id}"`,p.id===state.selectedProject)).join('')+'<div class="menu-separator"></div>'+menuItem('create-project','New project','plus'));return;}
if(a==='choose-project'){state.selectedProject=id;closeOverlay();render();return;}
if(a==='select-model'){popover(el,`<div class="menu-caption">Model · prototype options</div>`+['Auto','Doubao','DeepSeek','Claude'].map(m=>menuItem('choose-model',m,'star',`data-value="${m}"`,state.model===m)).join(''));return;}
if(a==='choose-model'){state.model=el.dataset.value;closeOverlay();render();return;}
if(a==='capability'){const value=el.dataset.value;if(state.capabilities.includes(value))state.capabilities=state.capabilities.filter(c=>c!==value);else state.capabilities.push(value);render();return;}
if(a==='more-capabilities'){popover(el,['Data Visualization','Product Prototype','Office','Image'].map(m=>menuItem('choose-capability',m,'grid',`data-value="${m}"`,state.capabilities.includes(m))).join(''));return;}
if(a==='choose-capability'){const value=el.dataset.value;state.capabilities=state.capabilities.includes(value)?state.capabilities.filter(x=>x!==value):[...state.capabilities,value];closeOverlay();render();toast('已'+(state.capabilities.includes(value)?'启用 ':'关闭 ')+value);return;}
if(a==='attach-menu'){popover(el,menuItem('upload-attachment','Upload a file','upload')+menuItem('select-library-file','Choose from Library','library'));return;}
if(a==='upload-attachment'){closeOverlay();const input=document.createElement('input');input.type='file';input.addEventListener('change',()=>{if(input.files[0]){state.attachment=input.files[0].name;render();toast('附件已加入演示任务，仅记录文件名称');}});input.click();return;}
if(a==='select-library-file'){closeOverlay();modal('Choose a file',data.library.map(f=>`<button class="search-result" data-action="attach-library-file" data-id="${f.id}">${icon('file',18)}<span>${esc(f.name)}</span>${icon('plus',16)}</button>`).join(''));return;}
if(a==='attach-library-file'){state.attachment=data.library.find(f=>f.id===id)?.name||'';closeOverlay();render();return;}
if(a==='remove-attachment'){state.attachment='';render();return;}
if(a==='voice'){modal('Voice input',`<div class="modal-illustration">${icon('mic',36)}</div><p class="muted" style="text-align:center">语音转写交互演示</p><label class="form-field"><span>Transcript</span><textarea id="voice-text" placeholder="在这里输入模拟转写内容…"></textarea></label><p class="prototype-note">此原型不会调用麦克风。输入文字后可插入任务。</p>`,button('close','Cancel')+button('use-transcript','Insert into task','','','btn primary'));return;}
if(a==='use-transcript'){const value=$('#voice-text').value.trim();if(!value){$('#voice-text').focus();return;}state.draft+=(state.draft?'\n':'')+value;closeOverlay();render();return;}
if(a==='send-task'){if(!state.draft.trim())return;if(state.page==='task'){const t=taskBy(state.task);t.replies=t.replies||[];t.replies.push({prompt:state.draft.trim()});state.draft='';state.attachment='';persist();render();}else startTask(state.draft);return;}
if(a==='start-code-task'){const input=$('#code-prompt');if(!input.value.trim()){input.focus();return;}state.selectedProject=$('#code-project').value;startTask(input.value,'code');return;}
if(a==='followup-suggestion'){state.draft='请将以上内容整理为行动清单，并补充优先级和验收标准。';render();$('#task-prompt').focus();return;}
if(a==='copy-answer'){const t=taskBy(id);try{await navigator.clipboard.writeText(`${t.name}\n\n明确目标与范围，整理信息与优先级，形成可执行方案。\n\n演示结果：此内容来自本地交互原型。`);toast('已复制到剪贴板');}catch{modal('Copy answer',`<label class="form-field"><span>选择并复制以下内容</span><textarea readonly>${esc(t.name)}\n\n明确目标与范围，整理信息与优先级，形成可执行方案。</textarea></label>`);}return;}
if(a==='detail-tab'){state.detailTab=el.dataset.tab;render();return;}
if(a==='agent-menu'){popover(el,menuItem('edit-agent','Edit workmate','edit',`data-id="${id}"`)+menuItem('chat-agent','New task','chat',`data-id="${id}"`));return;}
if(a==='edit-instructions'||a==='add-context'){const field=a==='edit-instructions'?'instructions':'context';const agent=agentBy(state.agent);modal(field==='instructions'?'Edit instructions':'Edit work context',`<label class="form-field"><span>${field==='instructions'?'Instructions':'Work context'}</span><textarea id="agent-text" rows="9" style="min-height:240px">${esc(agent[field]||$('.instruction-box')?.textContent||'')}</textarea></label>`,button('close','Cancel')+button('save-agent-text','Save','','data-field="'+field+'"','btn primary'));return;}
if(a==='save-agent-text'){agentBy(state.agent)[el.dataset.field]=$('#agent-text').value;persist();closeOverlay();render();toast('已保存');return;}
if(a==='add-capability'){modal('Add capability',`<label class="form-field"><span>Capability name</span><input id="capability-name" placeholder="e.g. 竞品分析" maxlength="40"></label><p class="prototype-note">将能力添加到当前伙伴的演示配置。</p>`,button('close','Cancel')+button('save-capability','Add','','','btn primary'));return;}
if(a==='save-capability'){const name=$('#capability-name').value.trim();if(!name){$('#capability-name').focus();return;}const agent=agentBy(state.agent);agent.extraSkills=[...(agent.extraSkills||[]),name];agent.skills++;persist();closeOverlay();render();toast('已添加能力');return;}
if(a==='feishu-chat'){modal('Chat in Feishu',`<div class="modal-illustration">${icon('chat',42)}</div><p>在正式产品中，可通过飞书与伙伴继续对话。</p><p class="muted">此处可以体验同一伙伴的新建任务流程，消息仅保存在本地原型中。</p>`,button('close','Cancel')+button('chat-agent','Start demo chat','chat',`data-id="${state.agent}"`,'btn primary'));return;}
if(a==='demo-connect'){const agent=agentBy(state.agent);agent.demoConnected=!agent.demoConnected;persist();render();toast(agent.demoConnected?'演示连接已开启':'演示连接已断开');return;}
if(a==='create-automation'){closeOverlay();createAutomation();return;}
if(a==='save-automation'){const form=$('#automation-form');if(!form.reportValidity())return;const values=new FormData(form);if(!values.get('name').trim()||!values.get('description').trim())return;data.automations.unshift({id:'au'+Date.now(),name:values.get('name').trim(),description:values.get('description').trim(),schedule:values.get('frequency')+' at '+values.get('time'),enabled:true});persist();navigate('automations');toast('自动化演示已创建');return;}
if(a==='toggle-automation'){const auto=data.automations.find(a=>a.id===id);auto.enabled=!auto.enabled;persist();render();toast(auto.enabled?'自动化已恢复（演示）':'自动化已暂停（演示）');return;}
if(a==='create-project'){closeOverlay();createProject();return;}
if(a==='save-project'){const form=$('#project-form');if(!form.reportValidity())return;const values=new FormData(form);if(!values.get('name').trim())return;const id='p'+Date.now();data.projects.unshift({id,name:values.get('name').trim(),description:values.get('description').trim(),tasks:0,updated:'Just now'});persist();navigate('project',id);toast('项目已创建');return;}
if(a==='open-project'){navigate('project',id);return;}
if(a==='project-new-task'){state.selectedProject=id;state.draft='';navigate('new');return;}
if(a==='library-filter'){state.libraryFilter=el.dataset.filter;render();return;}
if(a==='hub-filter'){state.hubFilter=el.dataset.filter;render();return;}
if(a==='open-file'){showFile(id);return;}
if(a==='download-file'){downloadFile(id);return;}
if(a==='notifications'){notifications();return;}
if(a==='proactive'){modal('Proactive help',`<div class="row" style="margin-bottom:18px">${icon('moon',24)}<div><strong>A little help, at the right time.</strong><p class="muted" style="font-size:12px;margin:4px 0">让智能伙伴主动关注你的工作。</p></div></div><div class="proactive-row"><div class="grow">Proactive suggestions<p>在工作台中展示个性化任务建议。</p></div><button class="toggle ${data.proactive?'enabled':''}" role="switch" aria-checked="${!!data.proactive}" aria-label="Enable proactive suggestions" data-action="toggle-proactive"></button></div><p class="prototype-note">此设置只影响原型中的演示状态。</p>`,button('close','Done','','','btn primary'));return;}
if(a==='toggle-proactive'){data.proactive=!data.proactive;persist();el.classList.toggle('enabled',data.proactive);el.setAttribute('aria-checked',data.proactive);return;}
if(a==='profile'){popover(el,`<div class="menu-caption">设计工作空间 · Prototype</div>`+menuItem('help','Getting started','help')+menuItem('restore-quick','Show Quick start','grid')+menuItem('shortcuts','Keyboard shortcuts','keyboard')+'<div class="menu-separator"></div>'+menuItem('about','About this prototype','book'));return;}
if(a==='shortcuts'){closeOverlay();modal('Keyboard shortcuts',`<div class="proactive-row"><span class="grow">Search everything</span><span class="kbd">⌘ / Ctrl K</span></div><div class="proactive-row"><span class="grow">Send task</span><span class="kbd">⌘ / Ctrl Enter</span></div><div class="proactive-row"><span class="grow">Close dialog</span><span class="kbd">Esc</span></div>`);return;}
if(a==='help'){closeOverlay();modal('Your work, with a little help.',`<div class="help-steps">${[['选择一位伙伴','从工作台选择适合你的智能伙伴，也可以创建自己的伙伴。'],['开始一个任务','输入目标，选择项目与能力，然后点击发送。'],['让成果持续积累','在 Library 查看交付文件，在 Automations 体验周期任务。']].map(([title,desc],i)=>`<div class="help-step"><span class="step-number">${i+1}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`).join('')}</div>`,button('nav','Start a task','arrow','data-page="new"','btn primary'));return;}
if(a==='about'){closeOverlay();modal('About this prototype',`<div class="modal-illustration">${logo()}</div><p>参考 Doubao Workmates 工作台的高仿真产品交互原型。</p><p class="muted">支持智能伙伴管理、任务对话、全局搜索、项目空间、文件预览与自动化配置。</p><p class="prototype-note">使用通用演示数据；全部操作保存在当前浏览器，不连接真实飞书服务或 AI 模型。此为独立设计原型。</p>`);return;}
}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){void action(target,event);return;}if(event.target.matches('[data-backdrop]'))closeOverlay();});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='task-prompt'){state.draft=el.value;const send=document.querySelector('[data-action="send-task"]');if(send)send.disabled=!el.value.trim();}if(el.matches('[data-task-search]')){state.query=el.value;$('#task-results').innerHTML=taskRows();}if(el.id==='global-search')$('#global-results').innerHTML=searchResults(el.value);if(el.matches('[data-secondary-search]')){state.secondaryQuery=el.value;const pos=el.selectionStart;render();const input=$('[data-secondary-search]');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('submit',event=>event.preventDefault());
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();return;}if(event.key==='Escape'){closeOverlay();if(state.mobileOpen){state.mobileOpen=false;render();}return;}if((event.metaKey||event.ctrlKey)&&event.key==='Enter'&&$('#task-prompt')){event.preventDefault();document.querySelector('[data-action="send-task"]')?.click();return;}if((event.key==='Enter'||event.key===' ')&&event.target.matches('.agent-card')){event.preventDefault();navigate('detail',event.target.dataset.id);return;}const menu=$('.popover');if(menu&&['ArrowDown','ArrowUp','Home','End','Tab'].includes(event.key)){event.preventDefault();const items=[...menu.querySelectorAll('button')];const index=items.indexOf(document.activeElement);const next=event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowUp'||event.key==='Tab'&&event.shiftKey?-1:1)+items.length)%items.length;items[next]?.focus();return;}const dialog=$('[role="dialog"]');if(event.key==='Tab'&&dialog){const focusables=[...dialog.querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')].filter(e=>e.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.matchMedia('(max-width:680px)').addEventListener('change',()=>render());
window.addEventListener('popstate',()=>{closeOverlay();readRoute();});
// A prototype refresh finishes pending simulated tasks instead of leaving them stuck.
for(const task of data.tasks){if(task.status==='running')task.status='done';const seed=initialData.tasks.find(t=>t.id===task.id);if(seed&&!task.project)task.project=seed.project;}
readRoute();
